"""
L0 offline discrete-event pipeline-parallel schedule simulator (stdlib only).

Purpose (L0 scope, NOT a substitute for multi-GPU measurement):
  1. Provide a self-checkable reference frame for the bubble-rate measurement design.
  2. Self-check A: classic 1F1B must reproduce the analytic bubble ratio
     (p-1)/(m+p-1) under uniform-cost, zero-communication assumptions.
  3. Self-check B: work conservation -- total busy time and task count must be
     identical across schedules (1F1B / ZB(D)) for fixed (p, m, f, a, w).
  4. Self-check C: monotonicity of the makespan bubble floor in the pending
     weight-gradient budget D.

Everything produced here is an OFFLINE THEORETICAL REFERENCE. It is not a
measurement and must never be reported as a measured bubble rate.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

F, A, W = "F", "A", "W"   # forward / activation-grad / weight-grad


@dataclass(frozen=True)
class Task:
    kind: str
    stage: int
    mb: int

    @property
    def key(self):
        return (self.kind, self.stage, self.mb)


@dataclass
class SimConfig:
    p: int                      # pipeline stages
    m: int                      # microbatches
    f: float = 1.0              # per-chunk forward cost
    a: float = 1.0              # per-chunk activation-gradient cost
    w: float = 1.0              # per-chunk weight-gradient cost
    schedule: str = "1f1b"      # "1f1b" | "zb"
    max_pending_backward: Optional[int] = None   # D, ZB only
    comm: float = 0.0           # per-hop activation/gradient transfer penalty
    forward_lookahead: int = 10 ** 9             # in-flight microbatch memory bound


class Trace(list):
    """List of (stage, kind, mb, start, end) intervals."""
    def busy(self, stage: int) -> float:
        return sum(e - s for st, k, mb, s, e in self if st == stage)
    def kind_busy(self, stage: int, kind: str) -> float:
        return sum(e - s for st, k, mb, s, e in self if st == stage and k == kind)


class Simulator:
    def __init__(self, cfg: SimConfig):
        self.cfg = cfg
        self.trace: Trace = Trace()
        self.stage_free = [0.0] * cfg.p
        self.finish: Dict[Tuple, float] = {}
        self.remaining: List[Task] = []
        self._build()

    def _build(self):
        c = self.cfg
        for s in range(c.p):
            for i in range(c.m):
                self.remaining.append(Task(F, s, i))
                if c.schedule == "1f1b":
                    # weight gradient fused into the backward pass (classic 1F1B)
                    self.remaining.append(Task(A, s, i))
                else:
                    self.remaining.append(Task(A, s, i))
                    self.remaining.append(Task(W, s, i))

    # ---------- dependencies & costs ----------
    def cost(self, t: Task) -> float:
        c = self.cfg
        if t.kind == F:
            return c.f
        if t.kind == A:
            return c.a if c.schedule == "zb" else c.a + c.w
        return c.w

    def ready_time(self, t: Task, now: float) -> Optional[float]:
        """Earliest start time of task t given completed set, or None if not ready."""
        c, fin = self.cfg, self.finish
        if t.kind == F:
            if t.stage == 0:
                dep = 0.0
            else:
                k = (F, t.stage - 1, t.mb)
                if k not in fin:
                    return None
                dep = fin[k] + c.comm
            # in-flight memory bound: microbatch t.mb-? cannot exceed lookahead outstanding F
            out = sum(1 for i in range(c.m)
                      if ((F, t.stage, i) in fin) and ((A, t.stage, i) not in fin))
            if out >= c.forward_lookahead:
                return None
            return max(now, dep)
        if t.kind == A:
            k1 = (F, t.stage, t.mb)
            if k1 not in fin:
                return None
            d1 = fin[k1]
            if t.stage == c.p - 1:
                d2 = 0.0
            else:
                k2 = (A, t.stage + 1, t.mb)
                if k2 not in fin:
                    return None
                d2 = fin[k2] + c.comm
            return max(now, d1, d2)
        # W: needs A of same chunk; ZB memory constraint limits pending W per stage
        k1 = (A, t.stage, t.mb)
        if k1 not in fin:
            return None
        pending = sum(1 for i in range(c.m)
                      if ((A, t.stage, i) in fin) and ((W, t.stage, i) not in fin))
        if c.max_pending_backward is not None and pending > c.max_pending_backward:
            # executing more A first would exceed D; force W drain first (handled in priority)
            pass
        return max(now, fin[k1])

    def over_pending(self, stage: int) -> bool:
        c = self.cfg
        if c.schedule != "zb" or c.max_pending_backward is None:
            return False
        pending = sum(1 for i in range(c.m)
                      if ((A, stage, i) in self.finish) and ((W, stage, i) not in self.finish))
        return pending >= c.max_pending_backward

    def priority(self, t: Task, now: float) -> tuple:
        """Lower tuple == scheduled first among tasks ready at the same time."""
        if self.cfg.schedule == "1f1b":
            order = {A: 0, F: 1}
        else:
            # ZB: drain activation-grad first (frees the pipeline), then keep the
            # forward pass full (that is the zero-bubble claim), then insert W.
            order = {A: 0, F: 1, W: 2}
        if self.over_pending(t.stage) and t.kind == W:
            order = {A: 3, F: 4, W: 0}      # D bound reached: mandatory wgrad flush
        return (order[t.kind], t.mb, t.stage)

    # ---------- event loop ----------
    def run(self, cap: int = 4_000_000) -> Trace:
        steps = 0
        while self.remaining:
            best = None
            for t in self.remaining:
                st = self.stage_free[t.stage]
                rt = self.ready_time(t, st)
                if rt is None:
                    continue
                cand = (rt, self.priority(t, rt), t)
                if best is None or (cand[0], cand[1]) < (best[0], best[1]):
                    best = cand
            if best is None:
                raise RuntimeError("simulator deadlock: no ready task")
            start, _, t = best
            end = start + self.cost(t)
            self.trace.append((t.stage, t.kind, t.mb, start, end))
            self.finish[t.key] = end
            self.stage_free[t.stage] = end
            self.remaining.remove(t)
            steps += 1
            if steps > cap:
                raise RuntimeError("step cap exceeded")
        return self.trace


# ---------------- metrics ----------------
def makespan(tr: Trace) -> float:
    return max(e for _, _, _, _, e in tr)


def work_per_stage(tr: Trace, p: int) -> List[float]:
    return [tr.busy(s) for s in range(p)]


def agg_bubble_ratio(tr: Trace, p: int) -> float:
    """Aggregate GPU-idle fraction: 1 - sum_s busy_s / (p * T)."""
    T = makespan(tr)
    return 1.0 - sum(tr.busy(s) for s in range(p)) / (p * T)


def max_stage_bubble_ratio(tr: Trace, p: int) -> float:
    T = makespan(tr)
    return max(1.0 - tr.busy(s) / T for s in range(p))


def ideal_bound(tr: Trace, p: int) -> float:
    """Ideal-bound makespan: max_s busy_s (perfect packing lower bound)."""
    return max(tr.busy(s) for s in range(p))


def bound_bubble_ratio(tr: Trace, p: int) -> float:
    """Primary online metric mirrored offline: (T - T_lb) / T."""
    T, lb = makespan(tr), ideal_bound(tr)
    return (T - lb) / T


def forward_hole_ratio(tr: Trace, p: int, cfg: SimConfig) -> float:
    """H1 proxy: fraction of the forward-active window during which a stage was
    NOT executing a forward while at least one forward was still pending."""
    fwd_total = sum(tr.kind_busy(s, F) for s in range(p))
    T_fwd_end = max((e for _, k, _, _, e in tr if k == F), default=0.0)
    T_fwd_start = min((s for _, k, _, s, _ in tr if k == F), default=0.0)
    window = max(T_fwd_end - T_fwd_start, 1e-12)
    # aggregate stage-time available in the forward window minus forward busy time
    return max(0.0, 1.0 - fwd_total / (p * window)) if window > 0 else 0.0


def analytic_1f1b(p: int, m: int) -> float:
    return (p - 1) / (m + p - 1)
