"""
L0 idle-attribution analyzer (stdlib only).

Consumes a schedule trace of (stage, kind, mb, start, end) intervals and, for
every idle gap on every stage, classifies the CAUSE of the gap.  This is the
offline prototype of the exact post-processing that the real multi-GPU traces
must go through: a single aggregate "bubble rate" number is not admissible
evidence for a near-zero claim, an attribution is.

Gap classes (the taxonomy the online analyzer will use):
  fill            - gap before the stage's first task of the iteration
  drain           - gap after the stage's last task (tail wgrad flush etc.)
  fwd_hole        - a FORWARD task was ready at gap start but not run  (H1 target)
  bwd_hole        - an ACTIVATION-GRAD task was ready but not run
  wgrad_backlog   - only weight-grad work was ready (delayed-wgrad backlog)
  dep_or_comm     - nothing was ready: waiting on a cross-stage dependency
                    (incl. simulated communication)
  host_or_unknown - fallback for real traces (launch stalls, sync, profiler gaps)

All outputs are OFFLINE THEORETICAL REFERENCE values, never measurements.
"""
from __future__ import annotations
from collections import defaultdict
from typing import Dict, List, Sequence, Tuple

Interval = Tuple[int, str, int, float, float]   # stage, kind, mb, start, end
F, A, W = "F", "A", "W"


def _index(trace: Sequence[Interval], p: int):
    by_stage = defaultdict(list)
    endmap: Dict[Tuple, float] = {}
    startmap: Dict[Tuple, float] = {}
    for st, k, mb, s, e in trace:
        by_stage[st].append((k, mb, s, e))
        endmap[(k, st, mb)] = e
        startmap[(k, st, mb)] = s
    for st in by_stage:
        by_stage[st].sort(key=lambda r: r[2])
    return by_stage, endmap, startmap


def deps_ready(kind: str, stage: int, mb: int, t: float, p: int,
               endmap: Dict[Tuple, float], comm: float = 0.0) -> bool:
    """True iff every prerequisite of (kind, stage, mb) finished at or before t."""
    if kind == F:
        if stage == 0:
            return True
        e = endmap.get((F, stage - 1, mb))
        return e is not None and e + comm <= t
    if kind == A:
        e1 = endmap.get((F, stage, mb))
        if e1 is None or e1 > t:
            return False
        if stage == p - 1:
            return True
        e2 = endmap.get((A, stage + 1, mb))
        return e2 is not None and e2 + comm <= t
    e1 = endmap.get((A, stage, mb))
    return e1 is not None and e1 <= t


def attribute_idle(trace: Sequence[Interval], p: int, comm: float = 0.0,
                   eps: float = 1e-9) -> Dict[str, Dict[str, float]]:
    by_stage, endmap, startmap = _index(trace, p)
    T = max(e for _, _, _, _, e in trace)
    out: Dict[str, Dict[str, float]] = {f"s{st}": defaultdict(float) for st in range(p)}
    for st in range(p):
        rows = by_stage[st]
        first_start = rows[0][2]
        last_end = rows[-1][3]
        out[f"s{st}"]["fill"] += first_start
        out[f"s{st}"]["drain"] += max(0.0, T - last_end)
        for j in range(len(rows) - 1):
            g0, g1 = rows[j][3], rows[j + 1][2]
            gap = g1 - g0
            if gap <= eps:
                continue
            done = {(k, st, mb) for k, mb, _s, _e in rows if _e <= g0 + eps}
            pending = [(k, mb) for k, mb, _s, _e in rows if _s >= g1 - eps]
            ready = [(k, mb) for (k, mb) in pending
                     if (k, st, mb) not in done and deps_ready(k, st, mb, g0, p, endmap, comm)]
            kinds = {k for k, _ in ready}
            if F in kinds:
                out[f"s{st}"]["fwd_hole"] += gap
            elif A in kinds:
                out[f"s{st}"]["bwd_hole"] += gap
            elif W in kinds:
                out[f"s{st}"]["wgrad_backlog"] += gap
            else:
                out[f"s{st}"]["dep_or_comm"] += gap
    return out


def summarize(att: Dict[str, Dict[str, float]], p: int) -> Dict[str, float]:
    tot: Dict[str, float] = defaultdict(float)
    for st in range(p):
        for k, v in att[f"s{st}"].items():
            tot[k] += v
    idle = sum(tot.values())
    tot["idle_total"] = idle
    tot["idle_share"] = idle / (idle + sum(tot.values()) * 0 + 1e-30) if idle else 0.0
    return dict(tot)


def attribution_shares(trace: Sequence[Interval], p: int, comm: float = 0.0):
    """Returns (total_idle, {cause: share_of_idle}).  Irreducible causes:
    fill, drain, dep_or_comm.  Reducible: fwd_hole, bwd_hole, wgrad_backlog."""
    att = attribute_idle(trace, p, comm)
    tot: Dict[str, float] = defaultdict(float)
    for st in range(p):
        for k, v in att[f"s{st}"].items():
            tot[k] += v
    idle = sum(v for k, v in tot.items())
    shares = {k: (v / idle if idle > 1e-12 else 0.0) for k, v in tot.items()}
    irr = sum(tot[k] for k in ("fill", "drain", "dep_or_comm"))
    shares["irreducible_share_of_idle"] = (irr / idle) if idle > 1e-12 else 0.0
    return idle, shares


def ols_1_over_m(xs, ys):
    """Least squares y = slope*x + intercept on x = 1/m; used by the
    pre-registered asymptotic criterion (slope significant, intercept ~ 0)."""
    n = len(xs)
    mx, my = sum(xs) / n, sum(ys) / n
    sxx = sum((x - mx) ** 2 for x in xs)
    sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    slope = sxy / sxx if sxx else float("nan")
    inter = my - slope * mx
    resid = [y - (slope * x + inter) for x, y in zip(xs, ys)]
    s2 = sum(r * r for r in resid) / max(n - 2, 1)
    se = (s2 / sxx) ** 0.5 if sxx and s2 > 0 else 0.0
    return slope, inter, se
