def peak_pending(trace, p, eps=1e-9):
    """Peak memory-relevant residency per stage, derived from the schedule trace.
      peak_pending_wgrad  : max #(A done, W not started)  -> delayed weight-grad inputs held
      peak_held_inputs    : max #(F done, W not started)  -> activations kept alive
    These are the quantities that turn a theoretically near-zero bubble into a
    practically non-zero one (micro-batch shrink / recompute / OOM fallback)."""
    import bisect
    res = {}
    for st in range(p):
        ev = []
        for k, s_mb, _s, mb in [(r[0], r[3], r[2], r[1]) for r in trace if r[0] == st]:
            pass
        rows = [r for r in trace if r[0] == st]
        for k, _mb, s, e in rows:
            ev.append((s, +1 if k == F else 0, -0))     # placeholder
        # event sweep on completion times
        events = []
        for k, mb, s, e in rows:
            if k == F:
                events.append((e, "F"))
            elif k == A:
                events.append((e, "A"))
            else:
                events.append((e, "W"))
        events.sort()
        fa = fw = aw = 0
        pk_w = pk_h = 0
        for t, k in events:
            if k == "F":
                fa += 1
            elif k == "A":
                aw += 1
            else:
                fw += 1
                aw += 1  # keep counters consistent below
            pk_w = max(pk_w, aw - fw)              # A done, W not done
            pk_h = max(pk_h, fa - fw)              # F done, W not done
        res[st] = {"peak_pending_wgrad": pk_w, "peak_held_inputs": pk_h}
    return res
