"""L0 self-check suite for the offline reference frame (run: python3 selfcheck.py).
All numbers are OFFLINE THEORETICAL REFERENCE values, never measurements."""
import sys, random
sys.path.insert(0, '/workspace/l0_sim')
from pipeline_sim import (Simulator, SimConfig, makespan, bound_bubble_ratio,
                          agg_bubble_ratio, max_stage_bubble_ratio, analytic_1f1b)
from analyzer import attribution_shares, peak_pending, ols_1_over_m

F, A, W = "F", "A", "W"
def run(p, m, sched="zb", D=None, **kw):
    return Simulator(SimConfig(p=p, m=m, schedule=sched, max_pending_backward=D, **kw)).run()

def check(name, ok, detail=""):
    print("[%s] %s %s" % ("PASS" if ok else "FAIL", name, detail))
    return ok

def sc_anchor():
    ok = True
    for p in range(2, 9):
        for m in (4, 8, 12, 16, 32, 64, 96):
            sim = max_stage_bubble_ratio(run(p, m, "1f1b"), p)
            ok &= abs(sim - analytic_1f1b(p, m)) < 1e-9
    return check("SC-A 1F1B reproduces (p-1)/(m+p-1) exactly, p=2..8, 7 values of m", ok)

def sc_work():
    ok = True
    for p, m in ((2, 16), (4, 16), (8, 32)):
        t1, t2 = run(p, m, "1f1b"), run(p, m, "zb", 2 * p)
        ok &= sum(t1.busy(s) for s in range(p)) == sum(t2.busy(s) for s in range(p)) == 3 * p * m
    return check("SC-B work conservation: identical total busy (=3pm) across schedules", ok)

def sc_monotone():
    ok = True
    for p in (2, 4, 8):
        for m in (p, 2 * p, 4 * p, 8 * p):
            row = [makespan(run(p, m, "zb", D)) for D in (1, p, 2 * p - 1, 2 * p, 4 * p)]
            ok &= all(row[i] >= row[i + 1] - 1e-9 for i in range(len(row) - 1))
    return check("SC-C makespan non-increasing in pending budget D", ok)

def sc_instrument_sensitivity(inject_frac=0.25, delta=3.0):
    """Offline analogue of the C1 positive control: inject a KNOWN amount of
    forward-idle and verify the attribution recovers it.  If the analyzer cannot
    see an injected bubble it cannot certify a near-zero one."""
    p, m, D = 8, 32, 16
    tr = run(p, m, "zb", D)
    base_idle, base_sh = attribution_shares(tr, p)
    inj = []
    per_stage_n = None
    for st in range(p):
        frows = [i for i, r in enumerate(tr) if r[0] == st and r[1] == F]
        for idx in frows[:max(1, int(len(frows) * inject_frac))]:
            inj.append((st, tr[idx][2]))
    # rebuild trace with a forced delay before selected forward chunks
    delay = {st: 0.0 for st in range(p)}
    targets = set(inj)
    newtr = []
    for st, k, mb, s, e in sorted(tr, key=lambda r: (r[0], r[3])):
        if (st, mb) in targets and k == F:
            delay[st] += delta
            targets.discard((st, mb))
            newtr.append((st, k, mb, s + delay[st], e + delay[st]))
        else:
            newtr.append((st, k, mb, s + delay[st], e + delay[st]))
    idle, sh = attribution_shares(newtr, p)
    recovered = sh.get("fwd_hole", 0.0)
    injected_time = len(inj) * delta * 1.0
    ok = recovered > 0.5 and abs(recovered - injected_time / idle) < 0.15
    print("     injected fwd-idle = %.1f time units (%d chunks x %.1f); analyzer recovered "
          "fwd_hole share = %.3f of idle; baseline fwd_hole share = %.3f"
          % (injected_time, len(inj), delta, recovered, base_sh.get('fwd_hole', 0.0)))
    return check("SC-D attribution recovers injected forward bubbles (instrument sensitivity)", ok)

def sc_floor_vs_threshold():
    print("     min m for the PERFECT-schedule floor to meet tau (uniform f=a=w=1):")
    for tau in (0.02, 0.05, 0.10):
        cells = []
        for p in (2, 4, 8):
            mm = (p - 1) * (1 - tau) / (3 * tau)
            cells.append("p=%d: m>=%.0f (m/p>=%.1f)" % (p, mm, mm / p))
        print("       tau=%2.0f%% -> %s" % (tau * 100, "; ".join(cells)))
    at_risk = []
    for p, m in ((4, 4), (8, 8), (8, 16)):
        fl = bound_bubble_ratio(run(p, m, "zb", 2 * p), p)
        at_risk.append((p, m, round(fl, 3)))
    print("     unattainable-at-5%% cases (offline floor already > 5%%): %s" % at_risk)
    return check("SC-E threshold 5% is NOT attainable at small m/p even for a perfect schedule",
                 all(fl > 0.05 for _, _, fl in at_risk))

def sc_memory():
    rows = []
    for p, m in ((4, 16), (8, 32)):
        for D in (1, p, 2 * p - 1, 2 * p):
            tr = run(p, m, "zb", D)
            pp = peak_pending(tr, p)
            rows.append((p, m, D, makespan(tr), round(bound_bubble_ratio(tr, p), 4),
                         max(v['peak_pending_wgrad'] for v in pp.values()),
                         max(v['peak_held_inputs'] for v in pp.values())))
    print("      p  m |  D | makespan | bound_bubble | peak_pending_wgrad | peak_held_inputs")
    for r in rows:
        print("     %2d %3d | %2d | %8.1f | %12.4f | %18d | %16d" % r)
    sat = {(4, 16), (8, 32)}
    ok = True
    for p, m in sat:
        ms = {D: makespan(run(p, m, "zb", D)) for D in (p, 2 * p - 1, 2 * p, 4 * p)}
        ok &= len(set(ms.values())) == 1
    return check("SC-F under uniform costs D>=p saturates: D=2p adds NO makespan gain but raises residency ceiling", ok)

def sc_asymptotic():
    out = []
    for p in (4, 8):
        ms, ys = [], []
        for k in (1, 2, 4, 8, 16):
            m = k * p
            ms.append(m); ys.append(bound_bubble_ratio(run(p, m, "zb", 2 * p), p))
        sl, itc, se = ols_1_over_m([1.0 / x for x in ms], ys)
        out.append((p, [round(y, 4) for y in ys], round(sl, 4), round(itc, 5)))
    for o in out:
        print("      p=%d bubble(m=multiples of p)=%s  OLS on 1/m: slope=%.4f intercept=%+.5f" % o)
    return check("SC-G bubble scales as 1/m with ~zero intercept (offline)",
                 all(abs(o[3]) < 0.005 for o in out))

if __name__ == "__main__":
    print("L0 SELF-CHECK SUITE -- offline reference only, not measurements\n")
    res = [sc_anchor(), sc_work(), sc_monotone(), sc_instrument_sensitivity(),
           sc_floor_vs_threshold(), sc_memory(), sc_asymptotic()]
    print("\nALL SELF-CHECKS PASSED: %s (%d/%d)" % (all(res), sum(res), len(res)))
