    ok &= all(row[i] >= row[i + 1] - 1e-9 for i in range(len(row) - 1))\n    return check(\"SC-C makespan non-increasing in pending budget D\", ok)\n\ndef sc_instrument_sensitivity(inject_frac=0.25, delta=3.0):\n    \"\"\"Offline analogue of the C1 positive control: inject a KNOWN amount of\n    forward-idle and verify the attribution recovers it.  If the analyzer cannot\n    see an injected bubble it cannot certify a near-zero one.\"\"\"\n    p, m, D = 8, 32, 16\n    tr = run(p, m, \"zb\", D)\n    base_idle, base_sh = attribution_shares(tr, p)\n    inj = []\n    per_stage_n = None\n    for st in range(p):\n        frows = [i for i, r in enumerate(tr) if r[0] == st and r[1] == F]\n        for idx in frows[:max(1, int(len(frows) * inject_frac))]:\n            inj.append((st, tr[idx][2]))\n    # rebuild trace with a forced delay before selected forward chunks\n    delay = {st: 0.0 for st in range(p)}\n    targets = set(inj)\n    newtr = []\n    for st, k, mb, s, e in sorted(tr, key=lambda r: (r[0], r[3])):\n        if (st, mb) in targets and k == F:\n            delay[st] += delta\n            targets.discard((st, mb))\n            newtr.append((st, k, mb, s + delay[st], e + delay[st]))\n        else:\n            newtr.append((st, k, mb, s + delay[st], e + delay[st]))\n    idle, sh = attribution_shares(newtr, p)\n    recovered = sh.get(\"fwd_hole\", 0.0)\n    injected_time = len(inj) * delta * 1.0\n    ok = recovered > 0.5 and abs(recovered - injected_time / idle) < 0.15\n    print(\"     injected fwd-idle = %.1f time units (%d chunks x %.1f); analyzer recovered \"\n          \"fwd_hole share = %.3f of idle; baseline fwd_hole share = %.3f\"\n          % (injected_time, len(inj), delta, recovered, base_sh.get('fwd_hole', 0.0)))\n    return check(\"SC-D attribution recovers injected forward bubbles (instrument sensitivity)\", ok)\n\ndef sc_floor_vs_threshold():\n    print(\"     min m for the PERFECT-schedule floor to meet tau (uniform f=a=w=1):\")\n    for tau in (0.0