def forward_eligibility(trace, p, comm=0.0, eps=1e-9):
    """Separates the TWO different things that 'forward bubble' can mean.

    For each stage we sweep its own timeline and maintain a 'forward debt': the
    set of forward chunks on that stage whose data dependency (upstream forward)
    has already completed but which have not started yet.  While the debt is
    non-empty the stage is FORWARD-ELIGIBLE, and the elapsed time splits into:

      fwd_idle_time     debt>0 and the stage is IDLE  -> a true forward bubble
                        (H1a: only possible if the implementation idles on
                        purpose, or on real HW because of host stalls / comm
                        waits / stream serialisation)
      fwd_defer_time    debt>0 and the stage is BUSY with A/W work -> structural
                        forward deferral (H1b: a different quantity!)

    Reporting only one of them silently changes the meaning of 'zero bubble',
    which is why the online instrument must log both.
    """
    per_stage = {}
    for st in range(p):
        rows = sorted([r for r in trace if r[0] == st], key=lambda r: r[3])
        upstream = {}
        for r in trace:
            if r[1] == F:
                upstream[(r[2], r[0])] = r[4]        # (mb, stage) -> forward end
        debt = []
        idle_t = defer_t = busy_total = 0.0
        for k, mb, s, e in rows:
            # release dependencies that completed before this interval started
            debt = [d for d in debt if not (upstream.get((d, st - 1), 0.0) + comm <= s)] if st else []
            # (rebuild debt properly below)
            pass
        # robust reconstruction: recompute debt from scratch at each interval boundary
        bounds = sorted({r[3] for r in rows} | {r[4] for r in rows})
        fwd_rows = {r[2]: (r[3], r[4]) for r in rows if r[1] == F}
        idle_t = defer_t = 0.0
        for a_t, b_t in zip(bounds[:-1], bounds[1:]):
            if b_t - a_t <= eps:
                continue
            debt_n = 0
            for mb, (fs, fe) in fwd_rows.items():
                ready_at = upstream.get((mb, st - 1), 0.0) + (comm if st else 0.0)
                if ready_at <= a_t + eps and fs >= b_t - eps:
                    debt_n += 1
            if debt_n == 0:
                continue
            running = [r for r in rows if r[3] <= a_t + eps and r[4] >= b_t - eps]
            seg = b_t - a_t
            if not running:
                idle_t += seg
            elif any(r[1] != F for r in running):
                defer_t += seg
        per_stage[st] = {"fwd_idle": idle_t, "fwd_defer": defer_t,
                         "fwd_busy": sum(r[4] - r[3] for r in rows if r[1] == F)}
    tot = {k: sum(v[k] for v in per_stage.values()) for k in ("fwd_idle", "fwd_defer", "fwd_busy")}
    elig = tot["fwd_idle"] + tot["fwd_defer"] + tot["fwd_busy"]
    tot["fwd_eligible_time"] = elig
    tot["fwd_idle_rate"] = tot["fwd_idle"] / elig if elig else 0.0
    tot["fwd_defer_rate"] = tot["fwd_defer"] / elig if elig else 0.0
    return tot
'''
